package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService defines the interface for user-related business logic
type UserService interface {
	GetAllUsers() []User
	CreateUser(u User) (User, error)
	GetUserByID(id string) (User, error)
}

// userService implements UserService
type userService struct {
	users map[string]User
	mutex sync.RWMutex
}

// NewUserService creates and returns a new UserService
func NewUserService() UserService {
	return &userService{
		users: make(map[string]User),
	}
}

func (s *userService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

func (s *userService) CreateUser(u User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	u.ID = uuid.New().String() // Use UUID for ID generation
	s.users[u.ID] = u
	return u, nil
}

func (s *userService) GetUserByID(id string) (User, error) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	if !ok {
		return User{}, fmt.Errorf("user not found")
	}
	return u, nil
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"experiment/internal/service"
)

// UserHandler handles HTTP requests for users
type UserHandler struct {
	Service service.UserService
}

// NewUserHandler creates and returns a new UserHandler
func NewUserHandler(s service.UserService) *UserHandler {
	return &UserHandler{Service: s}
}

// ServeHTTP implements the http.Handler interface for /users endpoint
func (h *UserHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/users/") {
		h.handleGetUserByID(w, r)
		return
	}

	switch r.Method {
	case http.MethodGet:
		h.handleGetUsers(w, r)
	case http.MethodPost:
		h.handleCreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandler) handleGetUsers(w http.ResponseWriter, r *http.Request) {
	list := h.Service.GetAllUsers()
	json.NewEncoder(w).Encode(list)
}

func (h *UserHandler) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.Service.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

func (h *UserHandler) handleGetUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")
	if id == "" {
		http.NotFound(w, r) // No ID provided, so it's not a specific user request
		return
	}

	user, err := h.Service.GetUserByID(id)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	// Initialize the UserService
	userService := service.NewUserService()

	// Initialize the UserHandler with the UserService
	userHandler := api.NewUserHandler(userService)

	// Register the handlers
	http.HandleFunc("/users", userHandler.ServeHTTP)
	http.HandleFunc("/users/", userHandler.ServeHTTP) // This will be handled by the UserHandler itself for specific IDs

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"experiment/internal/api"
	"experiment/internal/service"
)

func TestUserAPI(t *testing.T) {
	// Initialize the UserService
	userService := service.NewUserService()

	// Initialize the UserHandler with the UserService
	userHandler := api.NewUserHandler(userService)

	// Create a new ServeMux to register the handlers
	mux := http.NewServeMux()
	mux.Handle("/users", userHandler)
	mux.Handle("/users/", userHandler)

	// Test POST /users
	t.Run("CreateUser", func(t *testing.T) {
		newUser := service.User{Name: "Alice", Email: "alice@example.com"}
		body, _ := json.Marshal(newUser)
		req, _ := http.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(body))
		rr := httptest.NewRecorder()

		mux.ServeHTTP(rr, req)

		if status := rr.Code; status != http.StatusCreated {
			t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusCreated)
		}

		var createdUser service.User
		json.NewDecoder(rr.Body).Decode(&createdUser)
		if createdUser.Name != newUser.Name || createdUser.Email != newUser.Email || createdUser.ID == "" {
			t.Errorf("handler returned unexpected body: got %v", createdUser)
		}
	})

	// Test GET /users
	t.Run("GetAllUsers", func(t *testing.T) {
		req, _ := http.NewRequest(http.MethodGet, "/users", nil)
		rr := httptest.NewRecorder()

		mux.ServeHTTP(rr, req)

		if status := rr.Code; status != http.StatusOK {
			t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
		}

		var users []service.User
		json.NewDecoder(rr.Body).Decode(&users)
		if len(users) != 1 {
			t.Errorf("handler returned unexpected number of users: got %v want %v", len(users), 1)
		}
	})

	// Get a user ID to test GET /users/{id}
	var testUserID string
	// First, create a user to ensure there's at least one
	newUser := service.User{Name: "Bob", Email: "bob@example.com"}
	body, _ := json.Marshal(newUser)
	reqCreate, _ := http.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(body))
	rrCreate := httptest.NewRecorder()
	mux.ServeHTTP(rrCreate, reqCreate)
	var createdUser service.User
	json.NewDecoder(rrCreate.Body).Decode(&createdUser)
	testUserID = createdUser.ID


	// Test GET /users/{id}
	t.Run("GetUserByID", func(t *testing.T) {
		req, _ := http.NewRequest(http.MethodGet, "/users/"+testUserID, nil)
		rr := httptest.NewRecorder()

		mux.ServeHTTP(rr, req)

		if status := rr.Code; status != http.StatusOK {
			t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
		}

		var user service.User
		json.NewDecoder(rr.Body).Decode(&user)
		if user.ID != testUserID || user.Name != newUser.Name || user.Email != newUser.Email {
			t.Errorf("handler returned unexpected user: got %v", user)
		}
	})

	// Test GET /users/{id} with non-existent ID
	t.Run("GetUserByID_NotFound", func(t *testing.T) {
		req, _ := http.NewRequest(http.MethodGet, "/users/nonexistent-id", nil)
		rr := httptest.NewRecorder()

		mux.ServeHTTP(rr, req)

		if status := rr.Code; status != http.StatusNotFound {
			t.Errorf("handler returned wrong status code for not found: got %v want %v", status, http.StatusNotFound)
		}
	})
}
